const strip=document.querySelector('.day-strip');const detail=document.querySelector('#day-detail');
const tripName=document.body.dataset.trip || 'Yunnan';
const start=new Date((document.body.dataset.start || '2027-05-14')+'T00:00:00Z');
const days=Array.from({length:10},(_,i)=>new Date(start.getTime()+i*86400000));
function selectDay(i,focus=false){document.querySelectorAll('[role=tab]').forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1});detail.setAttribute('aria-labelledby',`day-${i}`);const label=i===0?'Start of your trip':i===9?'Heading home':'A day to make your own';detail.innerHTML=`<div class="day-title"><span class="day-number">${String(i+1).padStart(2,'0')}</span><div><h3>${days[i].toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'})}</h3><small>Day ${i+1} of 10 · ${tripName}</small></div></div><div class="day-plan"><b>${label}</b><p>No activities planned yet.<br>Destinations, activities, and travel between stops are still to be decided.</p></div>`;if(focus)document.querySelector(`#day-${i}`).focus()}
days.forEach((d,i)=>{const b=document.createElement('button');b.id=`day-${i}`;b.role='tab';b.setAttribute('aria-controls','day-detail');b.setAttribute('aria-label',d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}));b.innerHTML=`${d.toLocaleDateString('en-GB',{weekday:'short',timeZone:'UTC'})}<b>${d.getUTCDate()}</b>`;b.onclick=()=>selectDay(i);b.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%10;if(e.key==='ArrowLeft')next=(i+9)%10;if(e.key==='Home')next=0;if(e.key==='End')next=9;if(next!==undefined){e.preventDefault();selectDay(next,true)}};strip.append(b)});selectDay(0);
const sections=document.querySelectorAll('main section[id]');const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${e.target.id}`))}},{rootMargin:'-10% 0px -55% 0px'});sections.forEach(s=>observer.observe(s));
